namespace Semantic.Engine.Contracts.Commands;

/// <summary>
/// Starts a new agent session. Published by the Gateway and consumed by the Orchestrator saga.
/// </summary>
/// <remarks>
/// <see cref="SessionId"/> doubles as the saga correlation identifier and is generated by the Gateway
/// so that the client can open the event stream before the first token is produced.
/// </remarks>
public sealed record StartAgentSessionCommand
{
    /// <summary>Gets the unique session identifier used as the saga correlation identifier.</summary>
    public Guid SessionId { get; init; }

    /// <summary>Gets the first user prompt of the session. Must not be empty.</summary>
    public string Prompt { get; init; } = string.Empty;
}
